{"content": "# Makefile para Compilação do TCC
# Uso: make [target]

# Configurações
TEX_FILE = src/Monografia_config.tex
PDF_FILE = build/Monografia_config.pdf
BUILD_DIR = build
SRC_DIR = src

# Comandos
LATEX = pdflatex
BIBTEX = bibtex
LATEXMK = latexmk

# Opções do LaTeX
LATEX_FLAGS = -interaction=nonstopmode -file-line-error -output-directory=$(BUILD_DIR)
LATEXMK_FLAGS = -pdf -interaction=nonstopmode -file-line-error -outdir=$(BUILD_DIR) -cd

.PHONY: all clean build quick help install-deps

# Target padrão
all: build

# Compilação completa com latexmk
build:
	@echo "Compilando TCC com latexmk..."
	@mkdir -p $(BUILD_DIR)
	$(LATEXMK) $(LATEXMK_FLAGS) $(TEX_FILE)
	@echo "✅ Compilação concluída! PDF gerado em: $(PDF_FILE)"

# Compilação rápida (apenas pdflatex)
quick:
	@echo "Compilação rápida..."
	@mkdir -p $(BUILD_DIR)
	cd $(SRC_DIR) && $(LATEX) $(LATEX_FLAGS) ../$(TEX_FILE)
	@echo "✅ Compilação rápida concluída!"

# Compilação manual completa
manual:
	@echo "Compilação manual completa..."
	@mkdir -p $(BUILD_DIR)
	cd $(SRC_DIR) && $(LATEX) $(LATEX_FLAGS) ../$(TEX_FILE)
	cd $(BUILD_DIR) && $(BIBTEX) Monografia_config
	cd $(SRC_DIR) && $(LATEX) $(LATEX_FLAGS) ../$(TEX_FILE)
	cd $(SRC_DIR) && $(LATEX) $(LATEX_FLAGS) ../$(TEX_FILE)
	@echo "✅ Compilação manual concluída!"

# Limpeza dos arquivos de compilação
clean:
	@echo "Limpando arquivos de compilação..."
	rm -rf $(BUILD_DIR)/*
	@echo "✅ Limpeza concluída!"

# Limpeza completa (including PDF)
clean-all: clean
	@echo "Limpeza completa realizada!"

# Visualizar PDF
view:
	@if [ -f "$(PDF_FILE)" ]; then \
		echo "Abrindo PDF..."; \
		xdg-open "$(PDF_FILE)" 2>/dev/null || open "$(PDF_FILE)" 2>/dev/null || echo "❌ Não foi possível abrir o PDF automaticamente"; \
	else \
		echo "❌ PDF não encontrado. Execute 'make build' primeiro."; \
	fi

# Instalar dependências (se necessário)
install-deps:
	@echo "Verificando dependências LaTeX..."
	@which pdflatex > /dev/null || (echo "❌ pdflatex não encontrado. Instale TeX Live." && exit 1)
	@which bibtex > /dev/null || (echo "❌ bibtex não encontrado. Instale TeX Live." && exit 1)
	@which latexmk > /dev/null || (echo "❌ latexmk não encontrado. Instale TeX Live." && exit 1)
	@echo "✅ Todas as dependências estão instaladas!"

# Estatísticas do documento
stats:
	@if [ -f "$(PDF_FILE)" ]; then \
		echo "📊 Estatísticas do documento:"; \
		echo "Páginas: $$(pdfinfo "$(PDF_FILE)" 2>/dev/null | grep Pages | awk '{print $$2}' || echo 'N/A')"; \
		echo "Tamanho: $$(du -h "$(PDF_FILE)" | cut -f1)"; \
		echo "Última modificação: $$(stat -c %y "$(PDF_FILE)" 2>/dev/null | cut -d' ' -f1 || stat -f %Sm "$(PDF_FILE)" 2>/dev/null)"; \
	else \
		echo "❌ PDF não encontrado. Execute 'make build' primeiro."; \
	fi

# Ajuda
help:
	@echo "📚 Makefile para Compilação do TCC"
	@echo ""
	@echo "Targets disponíveis:"
	@echo "  all          - Compilação completa (padrão)"
	@echo "  build        - Compilação completa com latexmk"
	@echo "  quick        - Compilação rápida (apenas pdflatex)"
	@echo "  manual       - Compilação manual completa"
	@echo "  clean        - Remove arquivos de compilação"
	@echo "  clean-all    - Limpeza completa"
	@echo "  view         - Abre o PDF gerado"
	@echo "  stats        - Mostra estatísticas do documento"
	@echo "  install-deps - Verifica dependências"
	@echo "  help         - Mostra esta ajuda"
	@echo ""
	@echo "Exemplos:"
	@echo "  make         # Compilação completa"
	@echo "  make quick   # Compilação rápida"
	@echo "  make clean   # Limpar arquivos"", "filePath": "/workspaces/Pesquisa_GAD/Template_de_TCC_IFMS_TADS/Makefile"}

